const slides = Array.from(document.querySelectorAll('.slide'));
let current = 0;
function showSlide(index) {{
  current = Math.max(0, Math.min(slides.length - 1, index));
  slides.forEach((slide, idx) => slide.classList.toggle('active', idx === current));
}}
document.addEventListener('keydown', (event) => {{
  if (['ArrowRight', 'PageDown', ' '].includes(event.key)) showSlide(current + 1);
  if (['ArrowLeft', 'PageUp'].includes(event.key)) showSlide(current - 1);
}});
let touchStartX = 0;
document.addEventListener('touchstart', event => touchStartX = event.changedTouches[0].screenX, {{ passive: true }});
document.addEventListener('touchend', event => {{
  const delta = event.changedTouches[0].screenX - touchStartX;
  if (Math.abs(delta) > 45) showSlide(current + (delta < 0 ? 1 : -1));
}}, {{ passive: true }});
showSlide(0);
</script>
</body>
