  --orange: #ff8a5b;
  --pink: #ff5fa2;
  --violet: #ad8cff;
  --blue: #70a7ff;
  --green: #67e8a3;
  --red: #ff6b6b;
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}}

/* === BASE STAGE === */
html, body {{
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: 'Sora', sans-serif;
  overflow: hidden;
}}
body {{
  background:
    radial-gradient(circle at 10% 15%, rgba(85, 214, 255, .18), transparent 32%),
    radial-gradient(circle at 88% 20%, rgba(183, 246, 106, .13), transparent 28%),
    radial-gradient(circle at 70% 86%, rgba(255, 95, 162, .12), transparent 34%),
    #07111f;
}}
.presentation {{
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  overflow: hidden;
  position: relative;
}}
.slide {{
  height: 100vh;
  height: 100dvh;
  width: 100vw;
  overflow: hidden;
  position: absolute;
  inset: 0;
  opacity: 0;
  transform: translateX(4vw) scale(.985);
  pointer-events: none;
  transition: opacity .38s ease, transform .52s var(--ease-out-expo);
  padding: clamp(28px, 4vw, 64px);
  display: grid;
  grid-template-rows: auto 1fr auto;
  gap: clamp(12px, 1.8vh, 24px);
}}
.slide.active {{
  opacity: 1;
  transform: translateX(0) scale(1);
  pointer-events: auto;
}}
.slide::before {{
  content: '';
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,.035) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,.035) 1px, transparent 1px);
  background-size: clamp(34px, 3.2vw, 58px) clamp(34px, 3.2vw, 58px);
  mask-image: radial-gradient(circle at 50% 40%, black 0 52%, transparent 80%);
  pointer-events: none;
}}
.slide > * {{ position: relative; z-index: 1; }}

/* === TYPOGRAPHY === */
h1, h2, h3, p {{ margin: 0; }}
h1 {{
  font-family: 'Newsreader', serif;
  font-size: clamp(46px, 6.8vw, 102px);
  line-height: .92;
  letter-spacing: clamp(-4px, -.35vw, -1px);
  max-width: 12ch;
}}
h2 {{
  font-family: 'Newsreader', serif;
  font-size: clamp(30px, 4.2vw, 68px);
  line-height: .95;
  letter-spacing: clamp(-2.4px, -.2vw, -.8px);
  max-width: 16ch;
}}
h3 {{
  font-size: clamp(14px, 1.25vw, 22px);
  line-height: 1.15;
  font-weight: 700;
}}
p, li, td, th {{
  font-size: clamp(11px, 1.05vw, 18px);
  line-height: 1.35;
}}
.kicker, .meta, .eyebrow, .chip, .axis, .nav, .source {{
  font-family: 'IBM Plex Mono', monospace;
  text-transform: uppercase;
  letter-spacing: .09em;
}}
.kicker {{ color: var(--lime); font-size: clamp(10px, .85vw, 13px); font-weight: 600; }}
.meta {{ color: var(--muted); font-size: clamp(10px, .85vw, 14px); }}
.source {{ color: var(--dim); font-size: clamp(8px, .72vw, 11px); }}

/* === SHARED LAYOUT === */
.topbar, .footbar {{
  display: flex;
  justify-content: space-between;
  align-items: center;
  min-height: clamp(18px, 2.5vh, 34px);
}}
.nav {{ display: flex; gap: clamp(8px, 1vw, 14px); color: var(--dim); font-size: clamp(9px, .8vw, 12px); }}
.nav span.active-dot {{ color: var(--cyan); }}
.content {{
  min-height: 0;
  display: grid;
  align-items: center;
  gap: clamp(16px, 2vw, 34px);
}}
.two-col {{ grid-template-columns: .88fr 1.12fr; }}
.two-col-even {{ grid-template-columns: 1fr 1fr; }}
.panel {{
  background: linear-gradient(145deg, rgba(20, 43, 70, .86), rgba(9, 21, 37, .78));
  border: 1px solid var(--line);
  border-radius: clamp(18px, 2vw, 34px);
  box-shadow: 0 clamp(18px, 4vw, 54px) clamp(34px, 5vw, 80px) rgba(0,0,0,.35), inset 0 1px rgba(255,255,255,.08);
}}
.note {{ color: var(--muted); max-width: 42ch; }}
.accent {{ color: var(--cyan); }}
.good {{ color: var(--lime); }}
.warn {{ color: var(--orange); }}
.big-number {{
  font-family: 'Newsreader', serif;
  font-size: clamp(70px, 12vw, 190px);
  line-height: .78;
  letter-spacing: -.08em;
}}

/* === TITLE SLIDE === */
.title-grid {{ grid-template-columns: 1.05fr .95fr; align-items: end; }}
.hero-card {{
  min-height: min(56vh, 580px);
  padding: clamp(22px, 3vw, 46px);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  overflow: hidden;
}}
.hero-card::after {{
  content: '';
  position: absolute;
  width: clamp(220px, 34vw, 560px);
  height: clamp(220px, 34vw, 560px);
  right: calc(-1 * clamp(70px, 9vw, 150px));
  bottom: calc(-1 * clamp(120px, 14vw, 230px));
  border-radius: 50%;
  background: conic-gradient(from 120deg, var(--cyan), var(--lime), var(--gold), var(--pink), var(--cyan));
  opacity: .72;
  filter: blur(1px);
}}
.hero-stack {{ position: relative; z-index: 1; display: grid; gap: clamp(14px, 2vh, 26px); }}
.stat-stack {{ display: grid; gap: clamp(12px, 1.6vh, 22px); }}
.stat-card {{ padding: clamp(18px, 2vw, 28px); }}
.stat-card .label {{ color: var(--muted); font-family: 'IBM Plex Mono', monospace; font-size: clamp(10px, .85vw, 13px); text-transform: uppercase; }}
.stat-card .value {{ font-size: clamp(24px, 3.2vw, 52px); font-weight: 800; line-height: 1; margin-top: clamp(5px, .6vh, 10px); }}

/* === LINE CHART === */
.chart-card {{ padding: clamp(18px, 2vw, 32px); height: min(66vh, 650px); display: grid; grid-template-rows: auto 1fr auto; gap: clamp(8px, 1.2vh, 16px); }}
.legend {{ display: flex; flex-wrap: wrap; gap: clamp(6px, .6vw, 12px); align-items: center; }}
.legend-item {{ font-family: 'IBM Plex Mono', monospace; color: var(--muted); font-size: clamp(8px, .75vw, 12px); display: inline-flex; align-items: center; gap: 6px; }}
.swatch {{ width: clamp(14px, 1.2vw, 24px); height: 3px; border-radius: 99px; }}
.line-chart {{ width: 100%; height: 100%; min-height: 0; }}
.chart-label {{ font-family: 'IBM Plex Mono', monospace; font-size: 11px; fill: #91a8bd; }}
.chart-value {{ font-family: 'IBM Plex Mono', monospace; font-size: 12px; fill: #dcecff; font-weight: 600; }}

/* === BARS === */
.bars {{ display: grid; gap: clamp(8px, 1.1vh, 16px); }}
.bar-row {{ display: grid; grid-template-columns: clamp(92px, 10vw, 155px) 1fr clamp(36px, 4vw, 60px); gap: clamp(8px, 1vw, 14px); align-items: center; }}
.bar-label {{ font-weight: 700; color: var(--ink); font-size: clamp(11px, 1vw, 16px); }}
.bar-track {{ height: clamp(14px, 1.6vh, 23px); background: rgba(255,255,255,.075); border-radius: 99px; overflow: hidden; border: 1px solid rgba(255,255,255,.08); }}
.bar-fill {{ height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--cyan), var(--lime)); box-shadow: 0 0 22px rgba(85,214,255,.22); }}
.bar-val {{ font-family: 'IBM Plex Mono', monospace; color: var(--muted); font-size: clamp(10px, .9vw, 14px); text-align: right; }}
.primary-wrap {{ padding: clamp(18px, 2.2vw, 34px); }}
.primary-callout {{ display: grid; gap: clamp(10px, 1.2vh, 18px); padding: clamp(18px, 2vw, 32px); }}
.intent-grid {{ display: grid; grid-template-columns: repeat(4,1fr); gap: clamp(8px, .9vw, 14px); margin-top: clamp(12px, 1.5vh, 22px); }}
.intent {{ padding: clamp(10px, 1.2vw, 18px); background: rgba(255,255,255,.055); border: 1px solid var(--line); border-radius: clamp(12px, 1.4vw, 20px); }}
.intent strong {{ display: block; font-size: clamp(17px, 2vw, 32px); color: var(--gold); }}
.intent span {{ color: var(--muted); font-size: clamp(8px, .75vw, 12px); font-family: 'IBM Plex Mono', monospace; text-transform: uppercase; }}

/* === SATISFACTION === */
.sat-card {{ padding: clamp(16px, 1.8vw, 30px); max-height: min(68vh, 660px); }}
.sat-card .bars {{ gap: clamp(5px, .72vh, 11px); }}
.sat-card .bar-row {{ grid-template-columns: clamp(82px, 8.5vw, 130px) 1fr clamp(34px, 3.6vw, 52px); }}
.sat-card .bar-track {{ height: clamp(12px, 1.35vh, 19px); }}
.sat-card .bar-fill {{ background: linear-gradient(90deg, var(--violet), var(--cyan)); }}
.pill-note {{ display: inline-flex; width: fit-content; border: 1px solid rgba(183,246,106,.35); color: var(--lime); padding: clamp(7px, .8vw, 12px) clamp(10px, 1vw, 16px); border-radius: 999px; font-family: 'IBM Plex Mono', monospace; font-size: clamp(9px, .78vw, 12px); text-transform: uppercase; letter-spacing: .08em; }}

/* === DOMAIN TABLE === */
.domain-panel {{ padding: clamp(16px, 2vw, 32px); }}
.domain-table {{ width: 100%; border-collapse: separate; border-spacing: 0 clamp(7px, .9vh, 13px); }}
.domain-table th {{ color: var(--dim); font-family: 'IBM Plex Mono', monospace; text-transform: uppercase; letter-spacing: .09em; font-size: clamp(8px, .72vw, 11px); text-align: left; padding: 0 clamp(8px, .9vw, 14px); }}
.domain-table td {{ background: rgba(255,255,255,.055); border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); padding: clamp(8px, 1vh, 14px) clamp(8px, .9vw, 14px); }}
.domain-table td:first-child {{ border-left: 1px solid var(--line); border-radius: 14px 0 0 14px; color: var(--ink); font-weight: 650; }}
.domain-table td:last-child {{ border-right: 1px solid var(--line); border-radius: 0 14px 14px 0; }}
.heat {{ width: clamp(80px, 10vw, 150px); height: clamp(18px, 2vh, 30px); border-radius: 999px; background: linear-gradient(90deg, rgba(85,214,255,.2), rgba(85,214,255,.95)); position: relative; overflow: hidden; }}
.heat.ts {{ background: linear-gradient(90deg, rgba(183,246,106,.18), rgba(183,246,106,.95)); }}
.heat.java {{ background: linear-gradient(90deg, rgba(255,209,102,.2), rgba(255,209,102,.95)); }}
.heat.cpp {{ background: linear-gradient(90deg, rgba(255,138,91,.22), rgba(255,138,91,.95)); }}
.domain-lang {{ font-weight: 800; }}

/* === TAKEAWAYS === */
.takeaway-grid {{ display: grid; grid-template-columns: repeat(5,1fr); gap: clamp(10px, 1vw, 18px); align-items: stretch; }}
.takeaway {{ padding: clamp(14px, 1.5vw, 24px); display: grid; grid-template-rows: auto auto 1fr; gap: clamp(8px, 1vh, 14px); min-height: min(38vh, 350px); }}
.takeaway .num {{ font-family: 'IBM Plex Mono', monospace; color: var(--cyan); font-size: clamp(10px, .9vw, 14px); }}
.takeaway p {{ color: var(--muted); font-size: clamp(10px, .9vw, 15px); }}

/* === REVEAL MOTION === */
.reveal {{ opacity: 0; transform: translateY(24px); transition: opacity .52s var(--ease-out-expo), transform .52s var(--ease-out-expo); }}
.active .reveal {{ opacity: 1; transform: translateY(0); }}
.reveal:nth-child(2) {{ transition-delay: .06s; }}
.reveal:nth-child(3) {{ transition-delay: .12s; }}
.reveal:nth-child(4) {{ transition-delay: .18s; }}

/* === RESPONSIVE HEIGHT GUARDS === */
@media (max-height: 700px) {{
  .slide {{ padding: clamp(20px, 3vw, 44px); gap: clamp(8px, 1vh, 14px); }}
  h1 {{ font-size: clamp(38px, 5.8vw, 78px); }}
  h2 {{ font-size: clamp(26px, 3.6vw, 52px); }}
  .chart-card {{ height: min(64vh, 520px); }}
  .takeaway {{ min-height: min(34vh, 270px); }}
}}
@media (max-height: 600px) {{
  .stat-stack {{ grid-template-columns: repeat(3,1fr); }}
  .title-grid, .two-col, .two-col-even {{ grid-template-columns: 1fr 1fr; }}
  .hero-card {{ min-height: min(50vh, 420px); }}
  .domain-table {{ border-spacing: 0 5px; }}
}}
@media (max-height: 500px) {{
  .footbar {{ display: none; }}
  .slide {{ padding: clamp(14px, 2.5vw, 30px); }}
  .chart-card {{ height: 62vh; }}
  p, li, td, th {{ font-size: clamp(9px, .9vw, 13px); }}
}}
@media (prefers-reduced-motion: reduce) {{
  *, *::before, *::after {{ animation: none !important; transition: none !important; }}
}}
</style>
</head>
